BEGIN TRANSACTION READ ONLY;
SET LOCAL statement_timeout='5s';
SET LOCAL lock_timeout='500ms';
SET LOCAL application_name='ce1_ce100_readonly';
WITH policies AS (
 SELECT n.nspname AS schema,c.relname AS relation,p.polname AS policy,p.polcmd AS command,
 p.polpermissive AS permissive,
 ARRAY(SELECT CASE WHEN roleid=0 THEN 'public' ELSE pg_get_userbyid(roleid) END FROM unnest(p.polroles) roleid) AS roles,
 pg_get_expr(p.polqual,p.polrelid) AS using_expression,
 pg_get_expr(p.polwithcheck,p.polrelid) AS check_expression
 FROM pg_policy p JOIN pg_class c ON c.oid=p.polrelid JOIN pg_namespace n ON n.oid=c.relnamespace
 WHERE n.nspname='public' AND c.relname IN
 ('catalog_location_prices','mercadona_products','carrefour_products','consum_products','plusfresc_products')
), table_stats AS (
 SELECT schemaname,relname,n_live_tup,n_dead_tup,last_autovacuum,last_autoanalyze,
 last_vacuum,last_analyze
 FROM pg_stat_user_tables WHERE (schemaname='public' AND relname IN
 ('catalog_product_embeddings','catalog_location_prices','mercadona_products','carrefour_products','consum_products','plusfresc_products'))
 OR (schemaname='comparator_internal' AND relname IN ('catalog_embedding_runs','catalog_embedding_run_jobs'))
), statement_stats AS (
 SELECT count(*) AS tracked_entries,sum(calls) AS calls,sum(total_exec_time) AS total_exec_time_ms,
 max(max_exec_time) AS maximum_recorded_exec_time_ms
 FROM extensions.pg_stat_statements WHERE dbid=(SELECT oid FROM pg_database WHERE datname=current_database())
), archiver AS (
 SELECT archived_count,last_archived_time,failed_count,last_failed_time,stats_reset FROM pg_stat_archiver
), pipeline AS (
 SELECT mode FROM comparator_internal.catalog_embedding_pipeline_control LIMIT 1
), cron_config AS (
 SELECT jobid,jobname,active,schedule FROM cron.job WHERE jobid=17
)
SELECT jsonb_build_object('captured_at',clock_timestamp(),
 'catalog_policies',(SELECT jsonb_agg(to_jsonb(p) ORDER BY p.relation,p.policy) FROM policies p),
 'table_stats',(SELECT jsonb_agg(to_jsonb(s) ORDER BY s.schemaname,s.relname) FROM table_stats s),
 'statement_stats_cumulative',(SELECT to_jsonb(s) FROM statement_stats s),
 'archiver_cumulative',(SELECT to_jsonb(a) FROM archiver a),
 'pipeline',(SELECT to_jsonb(p) FROM pipeline p),
 'cron_17',(SELECT jsonb_agg(to_jsonb(c)) FROM cron_config c)
) AS evidence;
ROLLBACK;

BEGIN TRANSACTION READ ONLY;
SET LOCAL statement_timeout = '5s';
SET LOCAL lock_timeout = '500ms';
SET LOCAL application_name = 'ce1_ce100_readonly';
SELECT jsonb_build_object(
 'captured_at', clock_timestamp(),
 'transaction_read_only', current_setting('transaction_read_only'),
 'statement_timeout', current_setting('statement_timeout'),
 'lock_timeout', current_setting('lock_timeout'),
 'activity_excluding_self', (
  SELECT jsonb_build_object(
   'connections', count(*),
   'client_connections', count(*) FILTER (WHERE backend_type = 'client backend'),
   'active', count(*) FILTER (WHERE state = 'active'),
   'waiting_lock', count(*) FILTER (WHERE wait_event_type = 'Lock'),
   'idle_in_transaction', count(*) FILTER (WHERE state LIKE 'idle in transaction%'),
   'active_older_than_30s', count(*) FILTER (WHERE state = 'active' AND query_start < now() - interval '30 seconds')
  ) FROM pg_stat_activity WHERE pid <> pg_backend_pid()
 ),
 'database_stats', (
  SELECT jsonb_build_object('numbackends',numbackends,'deadlocks',deadlocks,'conflicts',conflicts,
   'xact_commit',xact_commit,'xact_rollback',xact_rollback,'temp_files',temp_files,'temp_bytes',temp_bytes,
   'stats_reset',stats_reset)
  FROM pg_stat_database WHERE datname=current_database()
 )
) AS evidence;
ROLLBACK;
